class Solution { fun maximumGap(nums: IntArray): Int { if (nums.size < 2) return 0; val low = nums.min(); val high = nums.max(); if (low == high) return 0; val size = maxOf(1, (high - low) / (nums.size - 1)); val count = (high - low) / size + 1; val mins = IntArray(count) { Int.MAX_VALUE }; val maxs = IntArray(count) { Int.MIN_VALUE }; val used = BooleanArray(count); for (n in nums) { val i = (n - low) / size; used[i] = true; mins[i] = minOf(mins[i], n); maxs[i] = maxOf(maxs[i], n) }; var best = 0; var previous = low; for (i in 0 until count) if (used[i]) { best = maxOf(best, mins[i] - previous); previous = maxs[i] }; return best } }